<?php
declare(strict_types=1);
namespace App;
final class Landing {
 public static function defaults(): array { return ['primaryColor'=>'#193e35','backgroundColor'=>'#fafbf7','buttonText'=>'Solicitar información','whatsapp'=>'']; }
 public static function visual(array $s): array {
  $r=self::defaults();foreach(['primaryColor','backgroundColor'] as $k){$v=$s[$k]??$r[$k];if(!is_string($v)||!preg_match('/^#[a-f0-9]{6}$/i',$v))throw new HttpError(422,'Color inválido.');$r[$k]=$v;}
  $r['buttonText']=Support::text($s['buttonText']??$r['buttonText'],100);
  $r['whatsapp']=Support::text($s['whatsapp']??'',20,false);if($r['whatsapp']!==''&&!preg_match('/^[1-9][0-9]{7,14}$/',$r['whatsapp']))throw new HttpError(422,'WhatsApp requiere código de país y números, sin +.');return $r;
 }
 public static function content(array $c): array {
  $title=Support::text($c['title']??null,200);$desc=Support::text($c['description']??'',20000,false);$price=$c['publicPrice']??null;
  if($price!==null&&($price===''||!is_numeric($price)||!is_finite((float)$price)||(float)$price<0||(float)$price>999999999))throw new HttpError(422,'Precio público inválido.');
  $images=$c['images']??[];if(!is_array($images)||count($images)>60)throw new HttpError(422,'Galería inválida.');$images=array_values(array_filter($images,fn($i)=>!is_string($i)||trim($i)!==''));if(count($images)>30)throw new HttpError(422,'Máximo 30 imágenes.');foreach($images as &$i){if(!is_string($i)||strlen($i)>2000||!Support::url(trim($i)))throw new HttpError(422,'Solo se permiten URLs HTTP o HTTPS para imágenes.');$i=trim($i);}unset($i);
  $features=$c['features']??[];if(!is_array($features)||count($features)>60)throw new HttpError(422,'Características inválidas.');$features=array_values(array_filter($features,fn($f)=>!is_string($f)||trim($f)!==''));if(count($features)>30)throw new HttpError(422,'Máximo 30 características.');$features=array_map(fn($f)=>Support::text($f,300),$features);
  return ['title'=>$title,'description'=>$desc,'publicPrice'=>$price===null?null:(float)$price,'images'=>array_values($images),'features'=>$features,'seoTitle'=>Support::text($c['seoTitle']??$title,200,false),'seoDescription'=>Support::text($c['seoDescription']??'',320,false),'visual'=>self::visual($c['visual']??[])];
 }
 public static function slug(mixed $v): string { $v=Support::text($v,180);if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$v))throw new HttpError(422,'El slug admite minúsculas, números y guiones.');return $v; }
 public static function create(array $p,string $owner): array {
  $m=json_decode($p['mapped_data'],true);$settings=Database::one('SELECT settings FROM template_settings WHERE user_id=?',[$owner]);$visual=$settings?json_decode($settings['settings'],true):self::defaults();
  $name=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$m['name']);$slug=trim(strtolower(preg_replace('/[^a-zA-Z0-9]+/','-',$name?:'producto')),'-');$slug=substr($slug,0,120).'-'.$m['id'].'-'.substr(str_replace('-','',Support::uuid()),0,8);
  $images=array_values(array_filter(array_map([Product::class,'image'],$m['images']??[])));
  $content=self::content(['title'=>$m['name'],'description'=>$m['description'],'publicPrice'=>null,'images'=>array_slice($images,0,30),'features'=>[],'seoTitle'=>$m['name'],'seoDescription'=>'','visual'=>$visual]);
  return Database::one('INSERT INTO landing_pages(id,user_id,selected_product_id,slug,product_snapshot,content) VALUES(?,?,?,?,?::jsonb,?::jsonb) RETURNING *',[Support::uuid(),$owner,$p['id'],$slug,$p['mapped_data'],Support::json($content)]);
 }
 public static function decode(array $r): array {foreach(['content','product_snapshot'] as $key)if(isset($r[$key])&&is_string($r[$key]))$r[$key]=json_decode($r[$key],true);return $r;}
 public static function render(array $row,bool $preview=false,string $notice=''): string {
  $r=self::decode($row);$c=$r['content'];$v=$c['visual'];$e=fn($s)=>Support::escape($s);$url=rtrim(Support::env('APP_URL'),'/').'/p/'.$r['slug'];$title=$c['seoTitle']?:$c['title'];$description=$c['seoDescription']?:substr($c['description'],0,300);
  if($preview&&isset($_GET['expires'],$_GET['signature']))foreach($c['images'] as &$image){if(str_starts_with($image,rtrim(Support::env('APP_URL'),'/').'/media/'))$image.='?'.http_build_query(['expires'=>$_GET['expires'],'signature'=>$_GET['signature']]);}unset($image);
  $robots=$preview?'noindex,nofollow':'index,follow';$gallery='';foreach($c['images'] as $i=>$image)$gallery.='<button class="gallery-image" type="button" data-gallery="'.$e($image).'" aria-label="Ver imagen '.($i+1).'"><img '.($i?'loading="lazy"':'fetchpriority="high"').' src="'.$e($image).'" alt="'.$e($c['title']).'"></button>';
  $features='';foreach($c['features'] as $f)$features.='<li>'.$e($f).'</li>';
  $price=$c['publicPrice']===null?'Consulta el precio':'$ '.number_format((float)$c['publicPrice'],0,',','.').' COP';
  $wa=$v['whatsapp']?'<a class="whatsapp" rel="noopener noreferrer" href="https://wa.me/'.$e($v['whatsapp']).'?text='.rawurlencode('Hola, quiero información sobre '.$c['title']).'">Consultar por WhatsApp</a>':'';
  $form=$preview?'<p class="notice">Previsualización privada. El formulario está desactivado.</p>':'<form id="lead-form" method="post" action="/p/'.$e($r['slug']).'/lead"><input type="hidden" name="csrf" value="'.$e($_SESSION['csrf']).'"><input type="hidden" name="idempotency_key" value="'.Support::uuid().'"><label class="trap" aria-hidden="true">Sitio web<input name="website" tabindex="-1" autocomplete="off"></label><div class="form-grid"><label>Nombre<input name="first_name" maxlength="100" required autocomplete="given-name"></label><label>Apellido<input name="last_name" maxlength="100" required autocomplete="family-name"></label><label>Email<input name="email" type="email" maxlength="254" required autocomplete="email"></label><label>Teléfono<input name="phone" type="tel" maxlength="30" required autocomplete="tel"></label></div><p>Al enviar autorizas que te contactemos para atender tu consulta sobre este producto.</p><button class="primary" type="submit">'.$e($v['buttonText']).'</button><p id="lead-status" role="status"></p></form>';
  $main=$c['images'][0]??'';$asset='/landing.css';
  return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$e($title).'</title><meta name="description" content="'.$e($description).'"><meta name="robots" content="'.$robots.'"><link rel="canonical" href="'.$e($url).'"><meta property="og:title" content="'.$e($title).'"><meta property="og:description" content="'.$e($description).'"><meta property="og:url" content="'.$e($url).'"><meta property="og:type" content="product">'.($main?'<meta property="og:image" content="'.$e($main).'">':'').'<link rel="stylesheet" href="'.$asset.'"></head><body style="--primary:'.$e($v['primaryColor']).';--paper:'.$e($v['backgroundColor']).'"><header><a class="brand" href="'.$e($url).'">zenzales<span>.</span></a>'.($preview?'<span>Borrador · vista privada</span>':'<span>Información del producto</span>').'</header><main>'.($notice?'<p class="notice" role="status">'.$e($notice).'</p>':'').'<section class="product-layout"><div><div class="hero-image">'.($main?'<img id="hero-image" src="'.$e($main).'" alt="'.$e($c['title']).'">':'<p>Sin imagen disponible</p>').'</div><div class="thumbnails">'.$gallery.'</div></div><article><p class="eyebrow">DESCUBRE TU PRÓXIMA ELECCIÓN</p><h1>'.$e($c['title']).'</h1><p class="price">'.$e($price).'</p><p class="description">'.$e($c['description']).'</p>'.($features?'<ul>'.$features.'</ul>':'').$wa.'<section class="contact"><h2>Recibe más información</h2>'.$form.'</section></article></section></main><footer>Zenzales · Consulta sobre este producto</footer><script src="/landing.js" defer></script></body></html>';
 }
}
